  occurredAt: string;
  payload: Payload;
}

export function runtimeEvent<Payload>(
  type: RuntimeEventType,
  requestId: string,
  traceId: string,
  payload: Payload,
  conversationId?: ConversationId,
): RuntimeEvent<Payload> {
  return {
    schemaVersion: PROTOCOL_VERSION,
    type,
    eventId: randomUUID(),
    requestId,
    traceId,
    ...(conversationId ? { conversationId } : {}),
    occurredAt: new Date().toISOString(),
    payload,
  };
}

